SELECT x->>'signature'signature,md5(p.prosrc)body_md5,
 CASE WHEN x->'metadata'='null'::jsonb THEN p.oid IS NULL OR (md5(p.prosrc)=x->>'new_hash'AND p.proowner='postgres'::regrole AND (to_jsonb(p)-ARRAY['oid','pronamespace','proowner','prosrc','prolang'])=x->'helper_metadata'AND p.prolang=(SELECT oid FROM pg_language WHERE lanname=x->>'helper_language'))
 ELSE p.proowner='postgres'::regrole AND to_jsonb(p)-ARRAY['oid','pronamespace','proowner','prosrc','prolang']=x->'metadata'AND p.prolang=(SELECT oid FROM pg_language WHERE lanname=x->>'language')END metadata_matches,
 CASE WHEN p.oid IS NULL THEN 'absent'WHEN md5(p.prosrc)=x->>'old_hash'THEN 'baseline'WHEN md5(p.prosrc)=x->>'new_hash'THEN 'candidate'ELSE 'drift'END state
FROM specs LEFT JOIN pg_proc p ON p.oid=to_regprocedure(x->>'signature')ORDER BY 1;
